-- Verificación 1. Debe devolver: 743, 626, 63, 38, 16.
SELECT
  COUNT(*) AS eventos_excel,
  COUNT(*) FILTER (WHERE evento = 'Nacimiento') AS nacimientos,
  COUNT(*) FILTER (WHERE evento = 'Muerte') AS muertes,
  COUNT(*) FILTER (WHERE evento = 'Aborto') AS abortos,
  COUNT(*) FILTER (WHERE evento = 'Retacto') AS retactos
