-- Verificación 2 de la campaña visible. Debe totalizar 704 eventos.
SELECT
  evento,
  COUNT(*) AS cantidad,
  MIN(fecha) AS primera_fecha,
  MAX(fecha) AS ultima_fecha
FROM pariciones
WHERE cliente_id = 'ganaderas'
  AND campania_id = 'campania-ganaderas-2026-2027'
GROUP BY evento
ORDER BY evento;
